import React, { ReactNode, useState, useEffect, Children, isValidElement } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number;
  onComplete?: () => void;
  component?: 'ul' | 'ol' | 'div';
}

/**
 * Animated List component that renders children with staggered animations
 * Uses a sequential approach to animate items one after another
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  className = '',
  staggerDelay = 0.05,
  onComplete,
  component = 'ul'
}) => {
  const [activeItemIndex, setActiveItemIndex] = useState(-1);
  const [isComplete, setIsComplete] = useState(false);
  const childArray = Children.toArray(children).filter(child => 
    child !== null && 
    (typeof child !== 'string' || child.trim() !== '')
  );

  // Reset animation when component mounts or children change
  useEffect(() => {
    setActiveItemIndex(-1);
    setIsComplete(false);

    // Start animation sequence after a small delay
    const timer = setTimeout(() => {
      setActiveItemIndex(0);
    }, 50);

    return () => clearTimeout(timer);
  }, [children]);

  // Handle item animation complete
  const handleItemAnimationComplete = (index: number) => {
    if (index === childArray.length - 1) {
      // All items animated
      setIsComplete(true);
      if (onComplete) onComplete();
    } else {
      // Animate next item
      setActiveItemIndex(index + 1);
    }
  };

  // Animation variants
  const itemVariants = {
    hidden: { opacity: 0, y: 2 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.15 } }
  };

  // Create component with proper tag
  const Component = component as any;

  return (
    <Component 
      className={className}
      style={{
        padding: 0,
        margin: 0,
        listStyle: 'none',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start'
      }}
    >
      {childArray.map((child, index) => (
        <AnimatePresence key={index} mode="wait">
          {(activeItemIndex >= index || isComplete) && (
            <motion.li
              style={{
                width: '100%',
                justifyContent: 'flex-start',
                listStyle: 'none'
              }}
              initial="hidden"
              animate="visible"
              variants={itemVariants}
              onAnimationComplete={() => {
                if (activeItemIndex === index) {
                  handleItemAnimationComplete(index);
                }
              }}
            >
              {child}
            </motion.li>
          )}
        </AnimatePresence>
      ))}
    </Component>
  );
};

export default AnimatedList;
